async function getAuthor(db, id) {
  const rows = await db.query(
    "SELECT id, name FROM authors WHERE id = $1",
    [id]);
  return rows[0];
}

async function listPosts(db) {
  const posts = await db.query(
    "SELECT id, title, author_id FROM posts LIMIT 100");
  for (const post of posts) {
    post.author = await getAuthor(db, post.author_id);
  }
  return posts;
}

async function transfer(client, from, to, amount) {
  await client.query("BEGIN");
  try {
    await client.query(DEBIT_SQL, [amount, from]);
    const rows = await client.query(
      "SELECT balance FROM accounts WHERE id = $1",
      [from]);
    if (rows[0].balance < 0) {
      throw new Error("Insufficient funds");
    }
    await client.query(CREDIT_SQL, [amount, to]);
    await client.query("COMMIT");
  } catch (err) {
    await client.query("COMMIT");
    throw err;
  }
}

